{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map unfurls over the ruined skyline.",
      "visual_description": "Mara spreads a hand-drawn map on a broken parapet overlooking the shattered royal city at dusk, brass compass spinning wildly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The lamp wakes with a warning.",
      "visual_description": "Oracle Lamp's single flame-eye flares green as it hovers beside Mara, casting long warning shadows across cracked cobblestones.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound for duty.",
      "visual_description": "Mara turns the key in Tin Fox's tail; the little metal fox stretches, blue glass eyes blinking awake under a fallen royal banner.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver arrives through a shop window.",
      "visual_description": "Glass Diver emerges feet-first from a tall cracked window, helmet fogged, coat shimmering with reflected lantern light and broken neon glyphs.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team studies the castle gates.",
      "visual_description": "From a rooftop, the four companions peer down at the massive iron castle gates wreathed in green smoke and tattered banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Tin Fox slips past an armored patrol.",
      "visual_description": "The tiny clockwork fox darts between the boots of clanking empty suits of armor marching in formation down a moonlit avenue.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp warns against the cursed tower.",
      "visual_description": "Oracle Lamp's flame flickers red as it floats before a leaning black tower wrapped in chains, refusing to let Mara step closer.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "A sleeping official blocks the alley.",
      "visual_description": "Sleeping Tax Collector snores on a stone bench, ledger pillow under cheek, stamped papers fluttering from his sleeves in the cold wind.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a great winged shape overhead.",
      "visual_description": "A vast shadow passes over the rooftops; Glass Diver presses against a wall, his coat catching the silhouette in its reflective folds.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Mara charts a hidden passage.",
      "visual_description": "By the glow of Oracle Lamp, Mara sketches a route through sewer tunnels onto her ink-stained map, compass needle pointing down.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver swims through a mirror.",
      "visual_description": "Glass Diver dives headfirst into a tall gilded mirror; ripples spread across its silvered surface as his coat tails vanish inside.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door demands a password.",
      "visual_description": "Three rune-carved doors pulse with violet light in a vaulted hall; Tin Fox sniffs each one while Mara consults her unrolled map.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Oracle Lamp speaks the unlocking word.",
      "visual_description": "Oracle Lamp's eye opens wide; a stream of golden script pours from its flame and the middle door swings open onto a dim staircase.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "They find the captive in a frozen window.",
      "visual_description": "Inside a frosted glass pane, the Sleeping Tax Collector is trapped mid-doze, ledger and all; Glass Diver presses a gloved palm to the surface.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Glass Diver pulls the sleeper free.",
      "visual_description": "Glass Diver heaves the snoring Sleeping Tax Collector out of a rippling windowpane like a swimmer rescuing a drowning man; papers swirl midair.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Tin Fox barks a metallic alarm.",
      "visual_description": "Tin Fox stands stiff-legged on a broken statue, jaw open in a tinny yelp, as armored shapes converge from every alley behind them.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The team races for the river bridge.",
      "visual_description": "All five sprint across a long stone bridge above black water, Oracle Lamp streaking ahead like a comet, the cursed city burning behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore at dawn.",
      "visual_description": "On a misty riverbank at sunrise, Mara folds her map, Glass Diver removes his helmet, Tin Fox curls at their feet, and the Sleeping Tax Collector finally stirs beside Oracle Lamp's calm flame.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    }
  ]
}

